    (UUID_TO_BIN('01a1e006-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-200000000001'), 'Dòng trước và dòng sau', 3, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-200000000001'), 'Cộng dồn và khung cửa sổ', 4, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lessons (id, chapter_id, lesson_key, slug, title, body, position, estimated_minutes, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000001'), 'window-function-la-gi', 'Window function khác GROUP BY thế nào', '## GROUP BY làm mất chi tiết\n\n```sql\nSELECT department, ROUND(AVG(salary)) AS avg_salary\nFROM employees\nGROUP BY department;\n```\n\nKết quả chỉ còn 4 dòng, mỗi phòng một dòng. Tên từng nhân viên đã biến mất.\n\n## Window function giữ nguyên từng dòng\n\nThêm `OVER (...)` sau hàm tổng hợp, nó trở thành **window function**: tính trên một khung dòng liên quan, rồi gắn kết quả vào **từng dòng**:\n\n```sql\nSELECT name, department, salary,\n       ROUND(AVG(salary) OVER ()) AS company_avg\nFROM employees;\n```\n\nVẫn đủ 13 nhân viên, mỗi dòng có thêm cột trung bình toàn công ty. `OVER ()` rỗng nghĩa là cửa sổ là **cả bảng**.\n\n## So sánh trực tiếp\n\n```sql\nSELECT name, salary,\n       salary - ROUND(AVG(salary) OVER ()) AS diff_from_company_avg\nFROM employees\nORDER BY diff_from_company_avg DESC NULLS LAST;\n```\n\nChặng Truy vấn lồng phải dùng subquery cho việc này. Window function làm gọn trong một tầng.\n\n## Window function chạy ở đâu\n\nWindow function được tính **sau** WHERE, GROUP BY, HAVING, và **trước** ORDER BY, LIMIT. Vì vậy không dùng được window function trong WHERE; muốn lọc theo nó, bọc trong CTE (chương 2).\n\n## Thử ngay\n\nÔ dưới cho mỗi sản phẩm giá, giá trung bình toàn bộ và giá cao nhất.', 1, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000002'), 'partition-by', 'PARTITION BY: cửa sổ theo nhóm', '## Chia cửa sổ thành từng nhóm\n\n`PARTITION BY` trong OVER chia các dòng thành nhóm, hàm chỉ tính **trong nhóm** của mỗi dòng:\n\n```sql\nSELECT name, department, salary,\n       ROUND(AVG(salary) OVER (PARTITION BY department)) AS dept_avg,\n       COUNT(*) OVER (PARTITION BY department) AS dept_size\nFROM employees\nORDER BY department, salary DESC NULLS LAST;\n```\n\nMỗi nhân viên thấy trung bình và quy mô của **chính phòng mình**.\n\n## Giống GROUP BY ở chỗ nào\n\n`PARTITION BY department` chia nhóm giống `GROUP BY department`. Khác biệt duy nhất: không gộp dòng.\n\n## Bài toán cũ, lời giải mới\n\nNhân viên lương cao hơn trung bình phòng mình, chặng trước dùng subquery tương quan:\n\n```sql\nWITH with_avg AS (\n    SELECT name, department, salary,\n           AVG(salary) OVER (PARTITION BY department) AS dept_avg\n    FROM employees\n)\nSELECT name, department, salary, ROUND(dept_avg) AS dept_avg\nFROM with_avg\nWHERE salary > dept_avg\nORDER BY department;\n```\n\n## Nhiều cửa sổ trong một truy vấn\n\nMỗi hàm có OVER riêng, có thể khác nhau: một cột theo phòng, một cột theo cả công ty, trên cùng một dòng.\n\n## Thử ngay\n\nÔ dưới cho mỗi sản phẩm giá cao nhất và số sản phẩm trong danh mục của nó.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000003'), 'order-by-trong-over', 'ORDER BY trong OVER', '## Thứ tự trong cửa sổ\n\n`ORDER BY` bên trong OVER quy định thứ tự các dòng **trong cửa sổ**. Nó cần cho các hàm phụ thuộc thứ tự như đánh số, lấy dòng trước, cộng dồn:\n\n```sql\nSELECT id, order_date,\n       ROW_NUMBER() OVER (ORDER BY order_date) AS order_seq\nFROM orders;\n```\n\n## Hai ORDER BY khác nhau\n\n- ORDER BY **trong OVER**: thứ tự dùng để **tính** window function.\n- ORDER BY **cuối câu lệnh**: thứ tự **hiển thị** kết quả.\n\nChúng độc lập. Câu dưới đánh số theo ngày nhưng hiển thị theo id giảm dần:\n\n```sql\nSELECT id, order_date,\n       ROW_NUMBER() OVER (ORDER BY order_date) AS order_seq\nFROM orders\nORDER BY id DESC;\n```\n\n## Kết hợp PARTITION BY và ORDER BY\n\nĐánh số đơn của **từng khách** theo thời gian:\n\n```sql\nSELECT customer_id, id, order_date,\n       ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date) AS nth_order\nFROM orders\nORDER BY customer_id, order_date;\n```\n\n`nth_order = 1` là đơn đầu tiên của mỗi khách.\n\n## Thử ngay\n\nÔ dưới đánh số nhân viên theo ngày vào làm trong từng phòng ban.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000004'), 'row-number-rank-dense-rank', 'ROW_NUMBER, RANK và DENSE_RANK', '## Ba cách xếp hạng\n\n```sql\nSELECT name, salary,\n       ROW_NUMBER() OVER (ORDER BY salary DESC NULLS LAST, id) AS row_number,\n       RANK() OVER (ORDER BY salary DESC NULLS LAST) AS rank,\n       DENSE_RANK() OVER (ORDER BY salary DESC NULLS LAST) AS dense_rank\nFROM employees\nORDER BY salary DESC NULLS LAST, id;\n```\n\nNhìn vào hai người cùng lương 18 triệu (Nguyễn Mai, Võ Tuấn) và hai người cùng 15 triệu (Kiều Nam, Tạ Linh):\n\n- `ROW_NUMBER`: luôn đánh 1, 2, 3... liên tục, người hoà nhau vẫn nhận số khác nhau. Ai đứng trước tuỳ cột phụ trong ORDER BY, ở đây là `id`.\n- `RANK`: người hoà nhau **cùng hạng**, và hạng sau **nhảy cóc**. Hai người hạng 8 thì người kế tiếp hạng 10.\n- `DENSE_RANK`: người hoà nhau cùng hạng, hạng sau **không nhảy**. Hai người hạng 8 thì người kế tiếp hạng 9.\n\n## Chọn hàm nào\n\n- Cần đúng một dòng mỗi vị trí (lấy bản ghi mới nhất, loại trùng): `ROW_NUMBER`.\n- Bảng xếp hạng thi đấu kiểu "đồng hạng nhì, không có hạng ba": `RANK`.\n- Muốn biết "mức lương cao thứ hai" là bao nhiêu, kể cả khi nhiều người cùng mức cao nhất: `DENSE_RANK`.\n\n## ROW_NUMBER cần cột phụ\n\nNếu ORDER BY trong OVER có giá trị bằng nhau, ROW_NUMBER chọn thứ tự tuỳ ý và có thể đổi giữa các lần chạy. Thêm một cột duy nhất như `id` để kết quả ổn định.\n\n## Thử ngay\n\nÔ thứ nhất so sánh ba hàm trên bảng lương. Ô thứ hai xếp hạng sản phẩm theo giá trong từng danh mục bằng RANK; thử đổi sang DENSE_RANK.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000005'), 'top-n-moi-nhom', 'Top N mỗi nhóm', '## Bài toán kinh điển\n\n> Hai nhân viên lương cao nhất của mỗi phòng ban.\n\nLIMIT chỉ cắt toàn bộ kết quả, không cắt theo nhóm. Window function giải quyết bằng hai bước: xếp hạng trong nhóm, rồi lọc theo hạng.\n\n```sql\nWITH ranked AS (\n    SELECT department, name, salary,\n           DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC NULLS LAST) AS salary_rank\n    FROM employees\n)\nSELECT department, name, salary, salary_rank\nFROM ranked\nWHERE salary_rank <= 2\nORDER BY department, salary_rank;\n```\n\n## Chọn hàm xếp hạng theo ý nghĩa\n\n- `ROW_NUMBER`: **đúng N người** mỗi phòng, người hoà nhau ở ranh giới bị cắt tuỳ cột phụ.\n- `DENSE_RANK` hoặc `RANK`: lấy **mọi người** ở N mức hạng đầu, có thể nhiều hơn N người nếu hoà.\n\nHãy hỏi lại người ra yêu cầu khi có hoà ở ranh giới. Đây là chỗ báo cáo hay bị cãi nhau nhất.\n\n## Bản ghi mới nhất của mỗi nhóm\n\nCùng mẫu đó lấy **đơn gần nhất** của mỗi khách:\n\n```sql\nWITH ranked_orders AS (\n    SELECT customer_id, id, order_date, status,\n           ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date DESC, id DESC) AS recency\n    FROM orders\n)\nSELECT customer_id, id AS last_order_id, order_date, status\nFROM ranked_orders\nWHERE recency = 1\nORDER BY customer_id;\n```\n\n## Thử ngay\n\nÔ dưới tìm sản phẩm bán chạy nhất (theo số lượng) của mỗi danh mục.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000006'), 'chia-nhom-voi-ntile', 'Chia nhóm đều với NTILE và PERCENT_RANK', '## NTILE: chia thành N phần gần bằng nhau\n\n```sql\nSELECT name, price,\n       NTILE(4) OVER (ORDER BY price DESC) AS price_quartile\nFROM products\nORDER BY price DESC;\n```\n\n20 sản phẩm chia 4 nhóm, mỗi nhóm 5 sản phẩm: nhóm 1 đắt nhất, nhóm 4 rẻ nhất. Nếu số dòng không chia hết, các nhóm đầu nhiều hơn một dòng.\n\n## PERCENT_RANK: vị trí theo phần trăm\n\n`PERCENT_RANK()` trả số từ 0 tới 1 cho biết dòng đứng ở đâu: 0 là đầu tiên, 1 là cuối cùng.\n\n```sql\nSELECT name, salary,\n       ROUND((PERCENT_RANK() OVER (ORDER BY salary))::numeric, 2) AS percentile\nFROM employees\nWHERE salary IS NOT NULL\nORDER BY salary;\n```\n\n## Ứng dụng\n\n- Chia khách thành nhóm theo chi tiêu: top 25%, 25% tiếp theo...\n- Xem một mức lương đứng ở phân vị nào trong công ty.\n\n## Thử ngay\n\nÔ dưới chia khách đã mua thành 3 nhóm theo tổng chi tiêu đơn đã giao.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000007'), 'lag-va-lead', 'LAG và LEAD', '## Lấy giá trị của dòng khác\n\n- `LAG(cột)`: giá trị của dòng **trước** trong cửa sổ.\n- `LEAD(cột)`: giá trị của dòng **sau**.\n\n```sql\nSELECT customer_id, id, order_date,\n       LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS previous_order,\n       LEAD(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS next_order\nFROM orders\nWHERE customer_id IN (1, 2)\nORDER BY customer_id, order_date;\n```\n\nĐơn đầu tiên của mỗi khách không có dòng trước nên `previous_order` là NULL. Đơn cuối không có dòng sau nên `next_order` là NULL.\n\n## Khoảng cách giữa hai lần mua\n\n```sql\nSELECT customer_id, order_date,\n       order_date - LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS days_since_previous\nFROM orders\nORDER BY customer_id, order_date;\n```\n\nNguyễn An mua lần thứ hai sau 27 ngày, nhưng giữa đơn tháng 4 và tháng 8 cách nhau 130 ngày.\n\n## Tham số mở rộng\n\n`LAG(cột, k, mặc_định)`: lấy dòng cách k dòng phía trước, nếu không có thì trả `mặc_định` thay cho NULL. Ví dụ `LAG(revenue, 1, 0)`.\n\n## Thử ngay\n\nÔ dưới tính khoảng cách giữa các lần mua của mọi khách. Thử dùng LEAD để tính số ngày tới lần mua kế tiếp.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000008'), 'tang-truong-theo-thang', 'Tăng trưởng so với tháng trước', '## Doanh thu tháng này so với tháng trước\n\nGhép ba kỹ thuật đã học: CTE tính doanh thu theo tháng, LAG lấy tháng trước, phép tính ra phần trăm.\n\n```sql\nWITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       LAG(revenue) OVER (ORDER BY month) AS previous_revenue,\n       ROUND(100.0 * (revenue - LAG(revenue) OVER (ORDER BY month))\n             / LAG(revenue) OVER (ORDER BY month), 1) AS growth_percent\nFROM monthly\nORDER BY month;\n```\n\n## Đặt tên cho cửa sổ\n\nLặp lại `OVER (ORDER BY month)` ba lần khá dài. Mệnh đề `WINDOW` đặt tên cho cửa sổ:\n\n```sql\nWITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       revenue - LAG(revenue) OVER w AS change\nFROM monthly\nWINDOW w AS (ORDER BY month)\nORDER BY month;\n```\n\n## Cẩn thận tháng bị thiếu\n\nNếu một tháng không có doanh thu, LAG sẽ so với tháng **có dữ liệu gần nhất** chứ không phải tháng liền trước. Khi cần chính xác, dựng khung tháng bằng CTE đệ quy như ở chặng trước rồi mới dùng LAG.\n\n## Thử ngay\n\nÔ dưới tính chênh lệch số đơn (mọi trạng thái) so với tháng trước.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000009'), 'tong-cong-don', 'Tổng cộng dồn', '## SUM với ORDER BY trong OVER\n\nKhi OVER có ORDER BY, `SUM` cộng từ dòng đầu **tới dòng hiện tại**, tạo tổng cộng dồn:\n\n```sql\nWITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       SUM(revenue) OVER (ORDER BY month) AS revenue_to_date\nFROM monthly\nORDER BY month;\n```\n\n`revenue_to_date` của tháng 6 là tổng từ tháng 1 tới tháng 6.\n\n## Cộng dồn theo từng nhóm\n\nThêm PARTITION BY để cộng dồn **riêng** cho mỗi khách:\n\n```sql\nWITH order_totals AS (\n    SELECT o.customer_id, o.id, o.order_date, SUM(oi.quantity * oi.unit_price) AS total\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    GROUP BY o.customer_id, o.id, o.order_date\n)\nSELECT customer_id, order_date, total,\n       SUM(total) OVER (PARTITION BY customer_id ORDER BY order_date, id) AS lifetime_value\nFROM order_totals\nORDER BY customer_id, order_date;\n```\n\n## Bẫy khi có giá trị trùng ở ORDER BY\n\nMặc định, các dòng **bằng nhau** ở cột ORDER BY được cộng **cùng lúc**. Hai đơn cùng ngày sẽ có cùng tổng cộng dồn. Thêm cột phụ duy nhất (`id`) như ví dụ trên để cộng từng dòng một.\n\n## Thử ngay\n\nÔ dưới đếm số khách đăng ký cộng dồn theo ngày.', 1, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000010'), 'khung-cua-so-va-trung-binh-truot', 'Khung cửa sổ và trung bình trượt', '## ROWS BETWEEN\n\nKhung cửa sổ cho biết hàm tính trên **những dòng nào** quanh dòng hiện tại:\n\n```\nROWS BETWEEN 2 PRECEDING AND CURRENT ROW\n```\n\nnghĩa là: 2 dòng trước và chính dòng hiện tại, tổng cộng 3 dòng.\n\n## Trung bình trượt 3 tháng\n\n```sql\nWITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       ROUND(AVG(revenue) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) AS moving_avg_3m\nFROM monthly\nORDER BY month;\n```\n\nTrung bình trượt làm mượt các tháng tăng giảm đột biến, giúp nhìn rõ xu hướng.\n\n## Các mốc của khung\n\n- `UNBOUNDED PRECEDING`: từ dòng đầu của cửa sổ.\n- `n PRECEDING`, `n FOLLOWING`: n dòng trước, sau.\n- `CURRENT ROW`: dòng hiện tại.\n- `UNBOUNDED FOLLOWING`: tới dòng cuối.\n\nVí dụ `ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING` là cả cửa sổ, hữu ích với `LAST_VALUE`.\n\n## ROWS và RANGE\n\n`ROWS` đếm theo **số dòng**. `RANGE` (mặc định khi có ORDER BY) gom các dòng **bằng giá trị** lại với nhau, đó chính là lý do của bẫy cộng dồn ở bài trước.\n\n## Thử ngay\n\nÔ dưới tính tổng giá trị 2 đơn gần nhất của mỗi khách (đơn hiện tại và đơn trước đó).', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000011'), 'ti-trong-trong-nhom', 'Tỉ trọng trong nhóm', '## Mỗi phần chiếm bao nhiêu phần trăm\n\nChia giá trị của dòng cho tổng của nhóm, tính bằng window function:\n\n```sql\nWITH category_revenue AS (\n    SELECT cat.name AS category, SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM order_items oi\n    JOIN orders o ON o.id = oi.order_id\n    JOIN products p ON p.id = oi.product_id\n    JOIN categories cat ON cat.id = p.category_id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY cat.name\n)\nSELECT category, revenue,\n       ROUND(100.0 * revenue / SUM(revenue) OVER (), 1) AS percent_of_total\nFROM category_revenue\nORDER BY revenue DESC;\n```\n\n## Tỉ trọng trong từng nhóm con\n\nMỗi nhân viên chiếm bao nhiêu phần trăm quỹ lương của phòng mình:\n\n```sql\nSELECT department, name, salary,\n       ROUND(100.0 * salary / SUM(salary) OVER (PARTITION BY department), 1) AS percent_of_department\nFROM employees\nWHERE salary IS NOT NULL\nORDER BY department, percent_of_department DESC;\n```\n\n## Window function trên kết quả GROUP BY\n\nWindow function chạy **sau** GROUP BY, nên dùng được trên kết quả đã gom: `SUM(SUM(x)) OVER ()` là tổng của các tổng nhóm. Cách viết này hợp lệ nhưng khó đọc; tách bằng CTE như ví dụ đầu thường rõ hơn.\n\n## Thử ngay\n\nÔ dưới tính tỉ trọng của từng tháng trong doanh thu cả năm.', 3, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e006-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-500000000012'), 'on-tap-window-function', 'Ôn tập: hoàn thành lộ trình', '## Bài toán tổng hợp\n\n> Với mỗi khách đã mua: số đơn, tổng chi tiêu đơn đã giao, hạng chi tiêu trong thành phố của họ, và số ngày trung bình giữa hai lần mua.\n\n```sql\nWITH order_gaps AS (\n    SELECT customer_id,\n           order_date - LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date, id) AS gap_days\n    FROM orders\n),\ndelivered_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n),\nsummary AS (\n    SELECT c.id, c.name, COALESCE(c.city, ''Chưa cập nhật'') AS city,\n           (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS orders,\n           COALESCE(s.spent, 0) AS spent,\n           (SELECT ROUND(AVG(g.gap_days)) FROM order_gaps g WHERE g.customer_id = c.id) AS avg_gap_days\n    FROM customers c\n    LEFT JOIN delivered_spend s ON s.customer_id = c.id\n    WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id)\n)\nSELECT name, city, orders, spent,\n       RANK() OVER (PARTITION BY city ORDER BY spent DESC) AS rank_in_city,\n       avg_gap_days\nFROM summary\nORDER BY city, rank_in_city;\n```\n\nMột truy vấn dùng gần đủ mọi thứ của lộ trình: JOIN, LEFT JOIN, GROUP BY, subquery tương quan, EXISTS, CTE, LAG và RANK.\n\n## Bạn đã đi qua\n\n1. **Truy vấn cơ bản**: SELECT, WHERE, NULL, ORDER BY, CASE.\n2. **Nối bảng**: INNER, LEFT, SELF, CROSS JOIN.\n3. **Gom nhóm**: COUNT, SUM, GROUP BY, HAVING.\n4. **Truy vấn lồng**: subquery, EXISTS, bẫy NOT IN.\n5. **CTE**: WITH, WITH RECURSIVE.\n6. **Window function**: xếp hạng, LAG, cộng dồn.\n\n## Bước tiếp theo\n\nVào mục **Luyện tập** và chọn bài theo chủ đề Window Function, CTE hoặc Subquery. Máy chấm sẽ kiểm tra lời giải của bạn trên cả dữ liệu ẩn, kể cả các trường hợp NULL và dòng trùng mà lộ trình này đã cảnh báo.', 4, 15, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lesson_cells (id, lesson_id, cell_key, position, starter_sql, dialect, dataset_version_id, dataset_variant_id, dataset_checksum, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000001'), 1, 'SELECT name, price,\n       ROUND(AVG(price) OVER ()) AS avg_price,\n       MAX(price) OVER () AS max_price\nFROM products\nORDER BY price DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000002'), 1, 'SELECT name, category_id, price,\n       MAX(price) OVER (PARTITION BY category_id) AS max_in_category,\n       COUNT(*) OVER (PARTITION BY category_id) AS products_in_category\nFROM products\nORDER BY category_id, price DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000003'), 1, 'SELECT department, name, hire_date,\n       ROW_NUMBER() OVER (PARTITION BY department ORDER BY hire_date) AS seniority_rank\nFROM employees\nORDER BY department, hire_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000004'), 1, 'SELECT name, salary,\n       ROW_NUMBER() OVER (ORDER BY salary DESC NULLS LAST, id) AS row_number,\n       RANK() OVER (ORDER BY salary DESC NULLS LAST) AS rank,\n       DENSE_RANK() OVER (ORDER BY salary DESC NULLS LAST) AS dense_rank\nFROM employees\nORDER BY salary DESC NULLS LAST, id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000005'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000005'), 2, 'SELECT category_id, name, price,\n       RANK() OVER (PARTITION BY category_id ORDER BY price DESC) AS price_rank\nFROM products\nORDER BY category_id, price_rank;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000006'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000006'), 1, 'WITH units AS (\n    SELECT p.category_id, p.name, SUM(oi.quantity) AS units_sold\n    FROM order_items oi\n    JOIN products p ON p.id = oi.product_id\n    WHERE p.category_id IS NOT NULL\n    GROUP BY p.category_id, p.id, p.name\n),\nranked AS (\n    SELECT category_id, name, units_sold,\n           RANK() OVER (PARTITION BY category_id ORDER BY units_sold DESC) AS units_rank\n    FROM units\n)\nSELECT category_id, name, units_sold\nFROM ranked\nWHERE units_rank = 1\nORDER BY category_id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000007'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000007'), 2, 'WITH ranked AS (\n    SELECT department, name, salary,\n           DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC NULLS LAST) AS salary_rank\n    FROM employees\n)\nSELECT department, name, salary, salary_rank\nFROM ranked\nWHERE salary_rank <= 2\nORDER BY department, salary_rank;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000008'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000008'), 1, 'WITH spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n)\nSELECT customer_id, spent,\n       NTILE(3) OVER (ORDER BY spent DESC) AS spend_tier\nFROM spend\nORDER BY spent DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000009'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000009'), 1, 'SELECT customer_id, id, order_date,\n       order_date - LAG(order_date) OVER (PARTITION BY customer_id ORDER BY order_date) AS days_since_previous\nFROM orders\nORDER BY customer_id, order_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000010'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000010'), 1, 'WITH monthly AS (\n    SELECT DATE_TRUNC(''month'', order_date)::date AS month, COUNT(*) AS orders\n    FROM orders\n    GROUP BY 1\n)\nSELECT month, orders,\n       orders - LAG(orders) OVER w AS change\nFROM monthly\nWINDOW w AS (ORDER BY month)\nORDER BY month;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000011'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000011'), 1, 'SELECT signup_date, name,\n       COUNT(*) OVER (ORDER BY signup_date, id) AS customers_so_far\nFROM customers\nORDER BY signup_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000012'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000012'), 2, 'WITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       SUM(revenue) OVER (ORDER BY month) AS revenue_to_date\nFROM monthly\nORDER BY month;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000013'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000013'), 1, 'WITH order_totals AS (\n    SELECT o.customer_id, o.id, o.order_date, SUM(oi.quantity * oi.unit_price) AS total\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    GROUP BY o.customer_id, o.id, o.order_date\n)\nSELECT customer_id, order_date, total,\n       SUM(total) OVER (PARTITION BY customer_id ORDER BY order_date, id\n                        ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS last_two_orders\nFROM order_totals\nORDER BY customer_id, order_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000014'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000014'), 1, 'WITH monthly AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT month, revenue,\n       ROUND(100.0 * revenue / SUM(revenue) OVER (), 1) AS percent_of_year\nFROM monthly\nORDER BY month;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e006-0000-7000-8000-600000000015'), UUID_TO_BIN('01a1e006-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e006-0000-7000-8000-700000000015'), 1, 'WITH ranked AS (\n    SELECT department, name, salary,\n           RANK() OVER (PARTITION BY department ORDER BY salary DESC NULLS LAST) AS salary_rank,\n           ROUND(100.0 * salary / SUM(salary) OVER (PARTITION BY department), 1) AS percent_of_department\n    FROM employees\n)\nSELECT *\nFROM ranked\nORDER BY department, salary_rank;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
